patch:
--- a/ports/picocalc/ai_psram_read_clock.hpp
+++ b/ports/picocalc/ai_psram_read_clock.hpp
@@ -3,10 +3,10 @@
 #include <cstdint>
 namespace picocalc::ai_psram_read_clock {
 // Only the qualified270MHz AI profile changes. Keep SPI and writes at their
-// normal divider. Six PIO cycles per SCK, so this bounds QPI reads to25MHz.
+// normal divider. Six PIO cycles per SCK, so this bounds QPI reads below33.334MHz.
 // The16-byte autonomous packet and its FIFO/CE# safety remain unchanged.
 constexpr std::uint32_t divider256(std::uint32_t sys,std::uint32_t normal) {
-  return sys==270000000 && normal==692 ? 461 : normal;
+  return sys==270000000 && normal==692 ? 346 : normal;
 }
 }
 #endif
--- a/tests/picocalc_ai_psram_read_clock_self_test.cpp
+++ b/tests/picocalc_ai_psram_read_clock_self_test.cpp
@@ -4,7 +4,7 @@
 int main(){using picocalc::ai_psram_read_clock::divider256;
 for(unsigned mhz=100;mhz<=300;++mhz)for(unsigned div=256;div<=768;++div){
  const unsigned got=divider256(mhz*1000000,div);
- if(mhz==270&&div==692)assert(got==461);else assert(got==div);
+ if(mhz==270&&div==692)assert(got==346);else assert(got==div);
 }
-assert(270000000ULL*256<=150000000ULL*divider256(270000000,692));
-std::puts("Only270MHz qualified AI QPI-read profile changes; <=25MHz SCK PASS");}
+assert(270000000ULL*256<=200000000ULL*divider256(270000000,692));
+std::puts("Only270MHz qualified AI QPI-read profile changes; <33.334MHz SCK PASS");}
